def test_rollback_rule_error_is_prefixed_with_forward_segment_number(self):
    groups, _back = self._rename_chain()
    back = [
        [],
        [{"op": "drop", "path": ["c", "x"]}],
    ]
    results = list(
        self.lens.migrate_path_stream(
            [{"a": 1}, {"a": 2}], [1, 2, 3], groups, back
        )
    )
    # The failing group belongs to forward segment 2 (it runs first
    # in the reverse order, but keeps the forward segment's number).
    self.assertEqual(
        results[0],
        {"index": 1, "report": None,
         "error": "rollback step 2: string path segment requires an object"},
    )
    self.assertIsNone(results[1]["error"])
    self.assertEqual(
        results[1]["report"]["rollback"]["record"], {"a": 2}
    )

